window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-05aa3cfc99a46ea9"]={"versions": [{"id": "FIG-05aa3cfc99a46ea9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation zeitlicher Randbedingungen im Kontext der AUTOSAR Adaptive Platform Timing Extensions (Subpaket <code>EventTriggeringConstraint</code>). Es modelliert die strukturellen Zeitparameter für sporadisch auftretende Ereignisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>EventTriggeringConstraint::SporadicEventTriggering</code> (Paket <code>EventTriggeringConstraint</code>): Repräsentiert die Randbedingung für sporadische Ereignisaktivierungen.\n</li><li><code>MultidimensionalTime::MultidimensionalTime</code> (Paket <code>MultidimensionalTime</code>): Dient als Typ für mehrdimensionale Zeitangaben mit den öffentlichen Attributen:\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType</code> (Kardinalität 1)\n</li><li><code>+ cseCodeFactor: Integer</code> (Kardinalität 1)\n</li></ul>\n</li><li>Kompositionen von <code>SporadicEventTriggering</code> auf <code>MultidimensionalTime</code>:\n<ul class=\"fig-list\"><li><code>+jitter</code>: Multiplizität <code>0..1</code>\n</li><li><code>+minimumInterArrivalTime</code>: Multiplizität <code>1</code>\n</li><li><code>+maximumInterArrivalTime</code>: Multiplizität <code>1</code>\n</li><li><code>+period</code>: Multiplizität <code>0..1</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Interaktionssequenzen. Die modellierten Zeitstrukturen definieren Grenzwerte (Mindest- und Höchstabstände sowie Jitter und Periodenbezug) für den zeitlichen Abstand aufeinanderfolgender Ereignisauslösungen zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klasse <code>SporadicEventTriggering</code> erfordert zwingend jeweils genau eine Spezifikation für <code>minimumInterArrivalTime</code> und <code>maximumInterArrivalTime</code> (Kardinalität 1). <code>jitter</code> und <code>period</code> sind optional (Kardinalität 0..1). Instanzen von <code>MultidimensionalTime</code> müssen die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> verpflichtend angeben.</p>"}, {"id": "FIG-de40d700d5b9e634", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation zeitlicher Randbedingungen im Kontext der AUTOSAR Adaptive Platform Timing Extensions (Subpaket <code>EventTriggeringConstraint</code>). Es modelliert die strukturellen Zeitparameter für sporadisch auftretende Ereignisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>SporadicEventTriggering</code> (im Paketkontext <code>EventTriggeringConstraint</code>): Repräsentiert die Randbedingung für sporadische Ereignisaktivierungen.\n</li><li><code>MultidimensionalTime</code>: Dient als Typ für mehrdimensionale Zeitangaben mit den öffentlichen Attributen:\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType</code> (Kardinalität 1)\n</li><li><code>+ cseCodeFactor: Integer</code> (Kardinalität 1)\n</li></ul>\n</li><li>Kompositionen von <code>SporadicEventTriggering</code> auf <code>MultidimensionalTime</code>:\n<ul class=\"fig-list\"><li><code>+jitter</code>: Multiplizität <code>0..1</code>\n</li><li><code>+minimumInterArrivalTime</code>: Multiplizität <code>1</code>\n</li><li><code>+maximumInterArrivalTime</code>: Multiplizität <code>1</code>\n</li><li><code>+period</code>: Multiplizität <code>0..1</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Interaktionssequenzen. Die modellierten Zeitstrukturen definieren Grenzwerte (Mindest- und Höchstabstände sowie Jitter und Periodenbezug) für den zeitlichen Abstand aufeinanderfolgender Ereignisauslösungen zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klasse <code>SporadicEventTriggering</code> erfordert zwingend jeweils genau eine Spezifikation für <code>minimumInterArrivalTime</code> und <code>maximumInterArrivalTime</code> (Kardinalität 1). <code>jitter</code> und <code>period</code> sind optional (Kardinalität 0..1). Instanzen von <code>MultidimensionalTime</code> müssen die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> verpflichtend angeben.</p>"}, {"id": "FIG-2cc9e90938bf1ec4", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation zeitlicher Randbedingungen im Kontext der AUTOSAR Adaptive Platform Timing Extensions (Subpaket <code>EventTriggeringConstraint</code>). Es modelliert die strukturellen Zeitparameter für sporadisch auftretende Ereignisse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert zwei Klassen und vier Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>SporadicEventTriggering</code> (im Paketkontext <code>EventTriggeringConstraint</code>): Repräsentiert die Randbedingung für sporadische Ereignisaktivierungen.\n</li><li><code>MultidimensionalTime</code>: Dient als Typ für mehrdimensionale Zeitangaben mit den Attributen:\n<ul class=\"fig-list\"><li><code>+ cseCode: CseCodeType [0..1]</code>\n</li><li><code>+ cseCodeFactor: Integer [0..1]</code>\n</li></ul>\n</li><li>Kompositionen von <code>SporadicEventTriggering</code> auf <code>MultidimensionalTime</code>:\n<ul class=\"fig-list\"><li><code>+jitter</code>: Multiplizität <code>0..1</code>\n</li><li><code>+minimumInterArrivalTime</code>: Multiplizität <code>0..1</code>\n</li><li><code>+maximumInterArrivalTime</code>: Multiplizität <code>0..1</code>\n</li><li><code>+period</code>: Multiplizität <code>0..1</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Interaktionssequenzen. Die modellierten Zeitstrukturen definieren Grenzwerte (Mindest- und Höchstabstände sowie Jitter und Periodenbezug) für den zeitlichen Abstand aufeinanderfolgender Ereignisauslösungen zur Laufzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Sämtliche Zeitparameter (<code>minimumInterArrivalTime</code>, <code>maximumInterArrivalTime</code>, <code>jitter</code>, <code>period</code>) von <code>SporadicEventTriggering</code> sind optional (Kardinalität jeweils <code>0..1</code>). Innerhalb von <code>MultidimensionalTime</code> sind die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> ebenfalls optional mit Multiplizität <code>[0..1]</code>. Modellersteller und Validierungswerkzeuge dürfen das Vorhandensein dieser Zeitgrenzen und Zeitattribute nicht mehr als zwingend voraussetzen.</p>"}], "trans": [{"from": "FIG-05aa3cfc99a46ea9", "to": "FIG-de40d700d5b9e634", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Klassennamen wurden von vollqualifizierter Schreibweise (<code>EventTriggeringConstraint::SporadicEventTriggering</code> bzw. <code>MultidimensionalTime::MultidimensionalTime</code>) auf einfache Namen (<code>SporadicEventTriggering</code> bzw. <code>MultidimensionalTime</code>) verkürzt.\n</li></ul>"}, {"from": "FIG-de40d700d5b9e634", "to": "FIG-2cc9e90938bf1ec4", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Kardinalitäten der Kompositionsrollen <code>minimumInterArrivalTime</code> und <code>maximumInterArrivalTime</code> wurden von <code>1</code> auf <code>0..1</code> geändert.\n</li><li>Die Multiplizitäten der Attribute <code>cseCode</code> und <code>cseCodeFactor</code> in <code>MultidimensionalTime</code> wurden explizit als <code>[0..1]</code> definiert (vorher implizit <code>1</code>).\n</li></ul>"}]};
